INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'BizPlanUserAuthGroup', 'DM', 'DMF0042 P_USERINFO 권한 그룹 (보유그룹 × GET_ADMIN_GROUP(ALL) 교집합)', 'SELECT M.USER_GR_ID AS CODE, M.USER_GR_ID AS NAME
FROM SCM_ADM_USER_GR_MPG_M M
WHERE M.USER_ID = @sesUserId
  AND M.USE_YN = ''Y''
  AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
              WHERE L.LOOKUP_TYPE = ''GET_ADMIN_GROUP'' AND L.VALID_YN = ''Y''
                AND L.SEGMENT1 = M.USER_GR_ID AND L.SEGMENT2 = ''ALL'')
ORDER BY DECODE(M.USER_GR_ID, ''ADMIN'', 1, 2), M.USER_GR_ID', 'Y', 'admin', TO_DATE('2026-07-15 13:01:50','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-07-15 13:01:50','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='BizPlanUserAuthGroup');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'BizTypeByDivision', 'CM', 'Biz Type by Division (AS-IS SCM0001_GET_BIZ_TYPE_BY_DIVISION 1:1 — @divisionId)', 'SELECT DISTINCT BIZ_TYPE AS CODE, BIZ_TYPE_NAME AS NAME
FROM SCM_MST_PROJECT
WHERE TRIM(BIZ_TYPE_NAME) IS NOT NULL
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || DIVISION_ID || '','') > 0)
ORDER BY CODE', 'Y', 'admin', TO_DATE('2026-07-01 14:39:29','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-07-23 21:36:22','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='BizTypeByDivision');

