INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'DMF0042_BP_Measure', 'DM', '[C] AS-IS @Code=''DMF0042_BP_Measure'' 수작업 통합 변환 — IF분기 통합 + DIVISION_ID 토', 'SELECT COLUMN_NAME AS CODE, COLUMN_LABEL_NAME AS NAME FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID = ''DMF0042'' AND SHEET_NAME = ''Biz Plan'' AND (NVL(TRIM(@divisionId), ''-'') = ''-'' OR INSTR('','' || DIVISION_ID || '','', '','' || @divisionId || '','') > 0) ORDER BY SORT_ORDER_NO', 'Y', 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS'), 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='DMF0042_BP_Measure');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'DM_LOOKUP_DIV', 'DM', '[C] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''DM_LOOKUP_DIV'' — ⚠ @param1(SEGMENT1)/@param', 'SELECT B.SEGMENT2 CODE ,B.SEGMENT3 NAME FROM SCM_ADM_LOOKUP_MASTER A INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.LOOKUP_TYPE = B.LOOKUP_TYPE AND B.VALID_YN = ''Y'' WHERE A.LOOKUP_TYPE = @param2 AND B.SEGMENT1 = @param1 AND A.VALID_YN = ''Y'' ORDER BY B.DISPLAY_SEQ', 'Y', 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS'), 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='DM_LOOKUP_DIV');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'DeptId', 'DM', '[C] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''DeptId''', 'SELECT DISTINCT B.DEPT_ID AS CODE , B.DEPT_NAME_KO AS NAME FROM SCM_MGR.SCM_MST_SITE A , SCM_MGR.SCM_MST_SSO_DEPT_INFO B WHERE A.DEPT_ID = B.DEPT_ID AND A.SITE_TYPE = ''SALES'' UNION ALL SELECT DISTINCT B.DEPT_ID AS CODE , B.DEPT_NAME_KO AS NAME FROM SCM_MGR.SCM_MST_SITE_ITEM A join SCM_MGR.SCM_MST_SSO_DEPT_INFO B ON B.DEPT_ID = ( SELECT SU.DEPT_ID FROM SCM_MGR.SCM_MST_SSO_USER_INFO su WHERE SU.USER_ID = A.OWNER )', 'Y', 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS'), 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='DeptId');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'DmBizType', 'DM', 'DM_BIZ_TYPE', 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME
FROM SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''DM_BIZ_TYPE''
ORDER BY DISPLAY_SEQ', 'Y', 'SYSTEM', TO_DATE('2026-05-29 10:53:36','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-07-23 20:57:02','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='DmBizType');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'EndCustomer', 'DM', 'EndCustomer', 'SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID,        CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE             ELSE A.END_CUSTOMER        END AS CODE,        NVL(D.SEGMENT3, CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE                             ELSE A.END_CUSTOMER                        END) AS NAME FROM SCM_MGR.SCM_MST_SITE A LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B              ON A.DIVISION_ID = B.DIVISION_ID             AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D              ON A.DIVISION_ID = D.SEGMENT1             AND A.END_CUSTOMER = D.SEGMENT2             AND D.LOOKUP_TYPE = ''END_CUSTOMER''             AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID IN (     SELECT DISTINCT UNIT_ID AS DIVISION_ID     FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M     WHERE USER_ID = @sesUserId       AND UNIT_TP_CD = ''D'' ) AND A.END_CUSTOMER IS NOT NULL ORDER BY DIVISION_ID, DEPT_ID, CODE', 'Y', 'SYSTEM', TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS'), 'SYSTEM', TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='EndCustomer');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'EndCustomerByDivision40', 'DM', '[C] AS-IS @Code=''EndCustomerByDivision40'' 수작업 통합 변환 — 빈 파라미터 0행 함정 ', 'SELECT DISTINCT C.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME
FROM SCM_MGR.SCM_MST_SITE_ITEM A
JOIN SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(CASE WHEN INSTR(A.OWNER, '','') > 0 THEN SUBSTR(A.OWNER, 1, INSTR(A.OWNER, '','') - 1) ELSE A.OWNER END)
JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID
LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y''
UNION
SELECT NULL AS DEPT_ID, SEGMENT2, SEGMENT3 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''END_CUSTOMER'' AND SEGMENT1 = ''40'' AND SEGMENT2 <> ''-'' AND VALID_YN = ''Y''
ORDER BY 2', 'Y', 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-08-05 17:26:17','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='EndCustomerByDivision40');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'EndCustomerByDivisionDept', 'DM', 'End Customer by division, team', 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID,     A.END_CUSTOMER AS CODE,     NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM ( 	SELECT DISTINCT 	     site.DIVISION_ID 	   , site.END_CUSTOMER 	   , item.DEPT_ID, item.PROJECT_CODE 	   , site.SCM_SITE_ID AS CODE 	   , site.SCM_SITE_ID AS NAME 	FROM      SCM_MST_SITE site 	LEFT JOIN SCM_MST_SITE_ITEM item 	       ON site.DIVISION_ID = item.DIVISION_ID 	      AND site.SCM_SITE_ID = item.SCM_SITE_ID ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D     ON A.DIVISION_ID = D.SEGMENT1    AND A.END_CUSTOMER = D.SEGMENT2    AND D.LOOKUP_TYPE = ''END_CUSTOMER''    AND D.VALID_YN = ''Y'' WHERE 1 = 1 --  AND ( --        (@divisionId = NULL OR @divisionId = ''ALL'' OR @divisionId = '''') --        OR A.DIVISION_ID IN ( --            SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND ( --        (@deptId = NULL OR @deptId = ''ALL'' OR @deptId = '''') --        OR A.DEPT_ID IN ( --            SELECT REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND A.DIVISION_ID IN ( --        SELECT DISTINCT UNIT_ID --        FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M --        WHERE USER_ID = @sesUserId --          AND UNIT_TP_CD = ''D'' --      )   AND A.DIVISION_ID IS NOT NULL   AND A.DEPT_ID IS NOT NULL   AND A.END_CUSTOMER IS NOT NULL ORDER BY A.END_CUSTOMER', 'Y', 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS'), 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='EndCustomerByDivisionDept');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'FromSiteByDivision', 'DM', '[C] AS-IS @Code=''FromSiteByDivision'' 수작업 통합 변환 — auth-ext(TB_FX_*) 필터 제거 —', 'SELECT SCM_SITE_ID AS CODE, SCM_SITE_ID AS NAME FROM SCM_MGR.SCM_MST_SITE A WHERE A.SITE_TYPE = ''PLANT'' AND A.VALID_YN = ''Y'' AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0) ORDER BY SCM_SITE_ID', 'Y', 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS'), 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='FromSiteByDivision');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'Incoterms', 'ALL', 'Incoterms 조회', 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''INCOTERMS'' AND   VALID_YN = ''Y'' --[PJ20228272] NERP 대응 - INCOTERMS Valid 추가 ORDER BY DISPLAY_SEQ', 'Y', 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS'), 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='Incoterms');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'IncotermsEdit', 'ALL', 'Incoterms', 'SELECT SEGMENT1 AS CODE 	 , SEGMENT2 AS NAME FROM   SCM_ADM_LOOKUP_MASTER_DETAIL WHERE  LOOKUP_TYPE = ''INCOTERMS''    AND VALID_YN = ''Y''    AND ATTRIBUTE2 = ''Y'' ORDER BY DISPLAY_SEQ', 'Y', 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS'), 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='IncotermsEdit');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'ItemType', 'DM', 'Item Type', 'SELECT        L.SEGMENT1  AS CODE,        L.SEGMENT2  AS NAME FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE  1 = 1 AND    L.LOOKUP_TYPE = ''ITEM_TYPE_CODE'' AND    L.VALID_YN    = ''Y'' ORDER BY L.DISPLAY_SEQ', 'Y', 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS'), 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='ItemType');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'MyDivision', 'DM', 'MyDivision', '  SELECT  T1.DIVISION_ID AS CODE, T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME) AS NAME 	FROM  SCM_MST_DIVISION T1 	JOIN  SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T2 	  ON  T1.DIVISION_ID = T2.UNIT_ID 	 AND  T2.UNIT_TP_CD = ''D''    WHERE  1=1 	 AND  T1.ATTRIBUTE3 <> ''EE'' 	 AND  T1.VALID_YN = ''Y'' 	 AND  T2.USE_YN = ''Y'' 	 AND  T2.USER_ID = @sesUserId GROUP BY  T1.DIVISION_ID, T1.ATTRIBUTE1 ORDER BY  T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME)', 'Y', 'SYSTEM', TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS'), 'SYSTEM', TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='MyDivision');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'PlantSitebyEndCustomer', 'DM', '[C] AS-IS @Code=''PlantSitebyEndCustomer'' 수작업 통합 변환 — auth-ext 제거 + 빈 파라미', 'SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME FROM SCM_MGR.SCM_MST_SITE A WHERE A.SITE_TYPE = ''PLANT'' AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0) AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0) ORDER BY CODE', 'Y', 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS'), 'minyonglee1', TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='PlantSitebyEndCustomer');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'SiteByEndCustomer', 'DM', 'SCM Site by End Customer', 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID, 	A.END_CUSTOMER AS END_CUSTOMER,     A.SCM_SITE_ID AS CODE,     A.SCM_SITE_ID AS NAME FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B     ON (@divisionId = ''40'' AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID) LEFT JOIN (     SELECT REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) AS token     FROM DUAL     CONNECT BY REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) IS NOT NULL ) C ON (1=1) WHERE A.SITE_TYPE = ''SALES''   AND A.VALID_YN = ''Y''   AND (         @divisionId IS NULL         OR @divisionId = ''''         OR @divisionId = ''ALL''         OR A.DIVISION_ID IN (             SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL)             FROM DUAL             CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL         )       )   AND (         @endCustomer IS NULL         OR @endCustomer = ''''         OR @endCustomer = ''ALL''         OR (             @divisionId <> ''40''             AND A.END_CUSTOMER = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN A.END_CUSTOMER                 ELSE C.token             END         )         OR (             @divisionId = ''40''             AND B.PROJECT_CODE = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN B.PROJECT_CODE                 ELSE C.token             END         )       )   AND A.DIVISION_ID IN (         SELECT DISTINCT UNIT_ID         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M         WHERE USER_ID = @sesUserId           AND UNIT_TP_CD = ''D''     ) ORDER BY A.SCM_SITE_ID ASC', 'Y', 'SYSTEM', TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-07-23 19:42:45','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='SiteByEndCustomer');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'UserSiteByEndCustomer', 'DM', 'Sales Site (AS-IS UP_FX SiteByEndCustomer/40 1:1 — @divisionId/@endCustomer/@deptId/@asYn)', 'SELECT CODE, NAME FROM (
SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 2 AS SORT_ORDER
FROM SCM_MST_SITE A
WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND A.DIVISION_ID <> ''40''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT DISTINCT A.SCM_SITE_ID, A.SCM_SITE_ID, 2
FROM SCM_MST_SITE A
LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
LEFT JOIN (SELECT DISTINCT U.USER_ID, U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U JOIN SCM_MST_SSO_DEPT_INFO D2 ON U.DEPT_ID = D2.DEPT_ID) C
  ON B.OWNER = C.USER_ID
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '',40,'') > 0)
  AND (NVL(TRIM(@deptId), ''ALL'') = ''ALL'' OR INSTR('','' || @deptId || '','', '','' || C.DEPT_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT L.SEGMENT1, B.SITE_DESCRIPTION, 1
FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
JOIN SCM_MST_SITE B ON L.SEGMENT3 = B.DIVISION_ID AND L.SEGMENT1 = B.SCM_SITE_ID
WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' AND B.VALID_YN = ''Y''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || L.SEGMENT3 || '','') > 0)
) ORDER BY SORT_ORDER, CODE', 'Y', 'admin', TO_DATE('2026-07-23 21:36:22','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-08-04 20:45:06','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='UserSiteByEndCustomer');

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'UserTeamByDivision', 'DM', 'DMF0003 UserTeamByDivision (AS-IS BigFilter/UP_FX 1:1)', 'SELECT DISTINCT A.DIVISION_ID AS DIVISION_ID, C.DEPT_ID AS CODE
     , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME
FROM SCM_MST_SITE_ITEM A, SCM_MST_SSO_USER_INFO B, SCM_MST_SSO_DEPT_INFO C
WHERE B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))
  AND B.DEPT_ID = C.DEPT_ID
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
ORDER BY DIVISION_ID, NAME, CODE', 'Y', 'admin', TO_DATE('2026-07-23 19:36:18','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-07-23 19:36:18','YYYY-MM-DD HH24:MI:SS') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M X WHERE X.SQL_ID='UserTeamByDivision');

-- ---- EndCustomerByDivision40 — DEPT_ID 확장본 동기화 (기존재 row 는 INSERT skip 되므로 UPDATE, 멱등) ----
UPDATE SCM_MGR.SCM_ADM_CMBO_SQL_M
   SET SQL_DTL_CTN = 'SELECT DISTINCT C.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME
FROM SCM_MGR.SCM_MST_SITE_ITEM A
JOIN SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(CASE WHEN INSTR(A.OWNER, '','') > 0 THEN SUBSTR(A.OWNER, 1, INSTR(A.OWNER, '','') - 1) ELSE A.OWNER END)
JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID
LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y''
UNION
SELECT NULL AS DEPT_ID, SEGMENT2, SEGMENT3 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''END_CUSTOMER'' AND SEGMENT1 = ''40'' AND SEGMENT2 <> ''-'' AND VALID_YN = ''Y''
ORDER BY 2'
     , LAST_UPDATED_BY = 'admin', LAST_UPDATE_DATE = SYSDATE
 WHERE SQL_ID = 'EndCustomerByDivision40'
   AND SQL_DTL_CTN NOT LIKE '%DEPT_ID%';

COMMIT;
